    29→func UnmarshalConfig(yamlFile []byte, conf *BeaconChainConfig) (*BeaconChainConfig, error) {
    30→	// To track if config name is defined inside config file.
    31→	hasConfigName := false
    32→	// Convert 0x hex inputs to fixed bytes arrays
    33→	lines := strings.Split(string(yamlFile), "\n")
    34→	if conf == nil {
    35→		if isMinimal(lines) {
    36→			conf = MinimalSpecConfig().Copy()
    37→		} else {
    38→			// Default to using mainnet.
    39→			conf = MainnetConfig()
    40→		}
    41→	}
    42→	for i, line := range lines {
    43→		// No need to convert the deposit contract address to byte array (as config expects a string).
    44→		if strings.HasPrefix(line, "DEPOSIT_CONTRACT_ADDRESS") {
    45→			continue
    46→		}
    47→		if strings.HasPrefix(line, "CONFIG_NAME") {
    48→			hasConfigName = true
    49→		}
    50→		if !strings.HasPrefix(line, "#") && strings.Contains(line, "0x") {
    51→			parts := ReplaceHexStringWithYAMLFormat(line)
    52→			lines[i] = strings.Join(parts, "\n")
    53→		}
    54→	}
    55→	yamlFile = []byte(strings.Join(lines, "\n"))
    56→	if err := yaml.UnmarshalStrict(yamlFile, conf); err != nil {
    57→		var typeError *yaml.TypeError
    58→		if !errors.As(err, &typeError) {
    59→			return nil, errors.Wrap(err, "Failed to parse chain config yaml file.")
